    state = 1

    def dist(p1, p2):
        return math.sqrt((p1[0] - p2[0])**2 + (p1[1] - p2[1])**2)

    def min_dist_on_segment(p1a, p2a, p1b, p2b):
        """Find minimum distance between line segments from p1a->p2a and p1b->p2b"""
        x1, y1 = p1a
        x2, y2 = p2a
        x3, y3 = p1b
        x4, y4 = p2b

        x10 = x1 - x2
        y10 = y1 - y2
        x30 = x3 - x4
        y30 = y3 - y4

        t1 = ((x1 - x3) * y30 - (y1 - y3) * x30) / (x10 * y30 - y10 * x30)
        t2 = ((x1 - x3) * y10 - (y1 - y3) * x10) / (x10 * y30 - y10 * x30)

        if t1 < 0 or t1 > 1:
            return dist((x1, y1), (x3, y3))
        if t2 < 0 or t2 > 1:
            return dist((x1, y1), (x3, y4))

        return dist((x3 + t2 * x30, y3 + t2 * y30), (x2 + t1 * x10, y2 + t1 * y10))

    for i in range(N):
        if dist(A[i], B[i]) <= d1:
            if state == 1 or dist(A[i-1], B[i-1]) > d2:
                count += 1
                state = 1
            else:
                state = 0
        else:
            dist_start = dist(A[i], B[i])
            dist_end = dist(A[i+1], B[i+1]) if i+1 < N else float('inf')

            min_d = dist_start
            if i+1 < N:
                min_d = min(min_d, dist(A[i], B[i+1]), dist(A[i+1], B[i]), dist(A[i], B[i]), dist(A[i+1], B[i+1]))

            if i+1 < N and min_d <= d1:
                state = 1

    return str(count)

