    def find_long_cycle():
        # Try BFS from each node to find cycles
        for start in range(1, n + 1):
            parent = {start: 0}
            depth = {start: 0}
            queue = deque([start])

            while queue:
                u = queue.popleft()

                for v in adj[u]:
                    if v == parent[u]:
                        continue
                    if v in parent:
                        # Found a back edge - cycle exists
                        # Cycle goes from v to u to ... back to v
                        cycle_len = depth[u] - depth[v] + 1
                        if cycle_len >= k:
                            # Reconstruct cycle
                            result = []
                            curr = u
                            while True:
                                result.append(curr)
                                if curr == v:
                                    break
                                curr = parent[curr]
                            result.append(v)
                            return "2\n" + str(len(result)) + "\n" + " ".join(map(str, result))
                    else:
                        parent[v] = u
                        depth[v] = depth[u] + 1
                        queue.append(v)

        return None

    cycle = find_long_cycle()
    if cycle:
        return cycle

    # If no long cycle, find independent set
