                if elements[i] not in prefix or prefix.count(prefix[-1]) < remaining:
                    # This is getting complex, let's use a simpler approach
                    pass
            return

        # Simpler: use itertools.permutations and deduplicate
        unique_perms = set()
        for p in __import__('itertools').permutations(elements):
            if is_good_arrangement(p):
                unique_perms.add(p)

        return len(unique_perms)

