    # Build adjacency of original complete binary tree
    orig_adj = defaultdict(set)

    for node in range(1, original_size + 1):
        if node == 1:
            # Root has 2 children at positions 2 and 3
            orig_adj[1].add(2)
            orig_adj[1].add(3)
            orig_adj[2].add(1)
            orig_adj[3].add(1)
        elif node % 2 == 0:
            # Even positions are left children
            parent = node // 2
            orig_adj[node].add(parent)
            orig_adj[parent].add(node)
        else:
            # Odd positions > 1 are right children
            parent = (node - 1) // 2
            orig_adj[node].add(parent)
            orig_adj[parent].add(node)

    # Remove removed_v from original
    temp_adj = defaultdict(set)
    for node in orig_adj:
        if node == removed_v:
            continue
        for neighbor in orig_adj[node]:
            if neighbor != removed_v:
                temp_adj[node].add(neighbor)

