def solution(input_str):
    """
    Find all starting positions in S where a substring of length |T| can be transformed 
    into T using pairwise letter substitutions.

    The transformation allows choosing pairs of letters (a,b), where each letter 
    appears in at most one pair, and each letter either maps to itself or to its pair.
    """
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s = lines[1]
    t = lines[2]

    results = []

    # Check each possible starting position
    for i in range(0, n - m + 1):
        char_pair = {}
        valid = True

        for j in range(m):
            c1 = s[i + j]
            c2 = t[j]

            if c1 == c2:
                # Same character, no pairing needed
                continue

            # c1 must map to c2, establishing pair (c1, c2)
            if c1 in char_pair:
                if char_pair[c1] != c2:
                    valid = False
                    break
            else:
                char_pair[c1] = c2

            # c2 must map back to c1 (symmetric pairs)
            if c2 in char_pair:
                if char_pair[c2] != c1:
                    valid = False
                    break
            else:
                char_pair[c2] = c1

        if valid:
            results.append(i + 1)  # 1-indexed positions

    return str(len(results)) + "\n" + " ".join(map(str, results))


