    # Try bases from x-1 down to 2
    for b in range(x - 1, 1, -1):
        # Try to find a prime p = k*n + 1 where ord_p(b) = n
        # We limit k search to reasonable bounds
        for k in range(1, 2000):
            p = k * n + 1

            # Check if p is prime
            if miller_rabin(p):
                # Check if b^n ≡ 1 (mod p)
                if pow(b, n, p) == 1:
                    # Check that no proper divisor d of n has b^d ≡ 1 (mod p)
                    found = True
                    for d in proper_divisors:
                        if pow(b, d, p) == 1:
                            found = False
                            break

                    if found:
                        # Found a valid (b, p) pair
                        # Set b and return it with newline
                        return f"{b}\n"

    return "-1\n"

