            if abs(val - i) >= K:
                count += 1
        if count == 0:
            has_valid = False
            break

    if not has_valid:
        return "-1"

    # Greedy approach to find lexicographically smallest permutation
    used = set()
    perm = []

    for i in range(1, N + 1):
        # Find smallest available value that satisfies the constraint
        placed = False
        for val in sorted(range(1, N + 1)):
            if val not in used and abs(val - i) >= K:
                used.add(val)
                perm.append(val)
