    lines = input_str.strip().split('\n')
    n = int(lines[0])

    # Read 2n cards
    cards = []
    for i in range(1, 2 * n + 1):
        a, b = map(int, lines[i].split())
        cards.append((a, b))

    # Find card by front value and by back value
    card_by_front = {}
    card_by_back = {}
    for i in range(len(cards)):
        front, back = cards[i]
        card_by_front[front] = i
        card_by_back[back] = i

    # Build dependency graph
    # For each k in [1,n]: card with front=k must come before card with back=-k
    adj = [[] for _ in range(2 * n)]
    in_degree = [0] * (2 * n)

    for k in range(1, n + 1):
        cf = card_by_front[k]      # card with front = k
        cb = card_by_back[-k]       # card with back = -k
        adj[cf].append(cb)
        in_degree[cb] += 1

    # Topological sort (Kahn's algorithm)
    from collections import deque
    queue = deque()
    for i in range(2 * n):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        u = queue.popleft()
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # Check if we got a valid topological sort (no cycle)
    if len(result) != 2 * n:
        return "NO"

    # Check if front sequence is balanced
    def is_balanced(seq):
        balance = 0
        for x in seq:
            balance += x
            if balance < 0:
                return False
        return balance == 0

    front_seq = [cards[i][0] for i in result]
    back_seq = [cards[i][1] for i in result]

    if is_balanced(front_seq) and is_balanced(back_seq):
        output_cards = [cards[i] for i in result]
        return "YES\n" + "\n".join(f"{a} {b}" for a, b in output_cards)
    else:
        return "NO"

