    cost_grid = [[0] * M for _ in range(N)]

    for i in range(1, K + 1):
        parts = lines[i].split()
        x, y, d, t, e = map(int, parts)

        # Calculate cost at each position (px, py) for each phase
        for phase in range(4):
            if phase == 0:
                px, py = x, y
            elif phase == 1:
                px, py = x + d, y - d
            elif phase == 2:
                px, py = x + d, y
            elif phase == 3:
                px, py = x, y + d

            # Check if this transformer can be at (px, py) at the time we arrive
            # We arrive at position (px, py) at time = px + py
            arrival_time = px + py

            if arrival_time >= t:
                if (arrival_time - t) % 4 == phase:
                    cost_grid[px][py] += e

    # dp[x][y] = min energy to reach position (x,y) starting from (0,0)
    dp = [[0] * M for _ in range(N)]

    # Initialize (0,0) - if cost_grid[0][0] > INF, it means we start there fine
    # Actually, cost is added when we ENTER each position, not before
    # So dp[0][0] should include the cost at (0,0)
    dp[0][0] = cost_grid[0][0]

    # Fill dp table row by row, left to right
    for x in range(N):
        for y in range(M):
            if x == 0 and y == 0:
                continue

            # Cost at current position
            current_cost = cost_grid[x][y]

            # From top (x-1, y)
            from_top = dp[x-1][y] if x > 0 else float('inf')
            # From left (x, y-1)
            from_left = dp[x][y-1] if y > 0 else float('inf')

            prev_min = min(from_top, from_left)

            if prev_min != float('inf'):
                dp[x][y] = prev_min + current_cost
            else:
                dp[x][y] = float('inf')

    return str(dp[N-1][M-1])

