    def is_capital_edge(u, v):
        return u == 1 or v == 1

    # Union-Find with path compression
    def build_mst_with_penalty(alpha):
        parent = list(range(n + 1))
        rank = [0] * (n + 1)

        def find(x):
            root = x
            while parent[root] != root:
                root = parent[root]
            while parent[x] != root:
                parent[x], x = root, parent[x]
            return root

        def union(x, y):
            px, py = find(x), find(y)
            if px == py:
                return False
            if rank[px] < rank[py]:
                px, py = py, px
            parent[py] = px
            if rank[px] == rank[py]:
                rank[px] += 1
            return True

