def solution(input_str):
    import sys
    sys.setrecursionlimit(200)

    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])

    # Precompute Fibonacci numbers up to 10^18
    MAX_N = 10**18
    fibs = [1, 2]
    while fibs[-1] <= MAX_N:
        fibs.append(fibs[-1] + fibs[-2])
    # Add one more for boundary
    fibs.append(fibs[-1] + fibs[-2])

    results = []

    for i in range(1, t + 1):
        n = int(lines[i])

        # Use BFS/DFS to count all valid decompositions
        # A decomposition is valid if sum of distinct Fibonacci numbers equals n

        memo = {}

        def count(start_idx, remaining):
            if remaining == 0:
                return 1
            if start_idx < 0:
                return 0
            if (start_idx, remaining) in memo:
                return memo[(start_idx, remaining)]

            total = 0
            f = fibs[start_idx]
            if f <= remaining:
                total += count(start_idx - 1, remaining - f) + count(start_idx - 1, remaining)
            else:
                total = count(start_idx - 1, remaining)

            memo[(start_idx, remaining)] = total
            return total

        # Start with largest Fibonacci that could work
        idx = len(fibs) - 2
        while idx >= 0 and fibs[idx] > n:
            idx -= 1

        ans = count(idx, n - fibs[idx]) + count(idx - 1, n)

        results.append(str(ans))

    return '\n'.join(results)

