def compute_inverse(perm):
    """Compute the inverse of a permutation.

    If perm = [p1, p2, ..., pn] where p[i] = value at position i,
    the inverse is [q1, q2, ..., qn] where q[p[i]] = i (1-indexed).

    For 0-indexed representation: inverse[val][position] = val,
    meaning position v corresponds to value inv[v].
    """
    n = len(perm)
    inv = [0] * (n + 1)
    for pos, val in enumerate(perm, 1):
        inv[val] = pos
    return inv[1:]

