            for i in range(n):
                temp = result[i]
                result[i] = temp[1:] + [temp[0]]
        elif op == 'D':
            # Down shift all rows
            if n > 0:
                first_row = result[0][:]
                for i in range(n - 1):
                    result[i] = result[i + 1][:]
                result[n - 1] = first_row
        elif op == 'U':
            # Up shift all rows
            if n > 0:
                last_row = result[-1][:]
                for i in range(n - 1):
                    result[i + 1] = result[i][:]
                result[0] = last_row
        elif op == 'I':
            # Invert each row's permutation
            new_result = []
            for i in range(n):
                inv_row = compute_inverse(result[i])
                new_result.append(inv_row)
            result = new_result
        elif op == 'C':
            # This is tricky - C inverts each column's permutation
            # To do this properly, we need to extract columns, invert, and place back
            new_result = [[0] * n for _ in range(n)]
            for j in range(n):
