                inv_col = compute_inverse(original_col)
                for i in range(n):
                    new_result[i][j] = inv_col[i]
            result = new_result

    return result

def solution(input_str):
    """
    Solve the matrix operations problem.

    Args:
        input_str: A string containing all test case data

    Returns:
        A string with the output for all test cases, separated by blank lines
    """
    lines = input_str.strip().split('\n')
    if not lines:
        return ""

    t = int(lines[0])
    idx = 1
    output = []

    for _ in range(t):
        if idx >= len(lines):
            break

        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            matrix.append(list(map(int, lines[idx].split())))
            idx += 1

        operations = lines[idx]
        idx += 1

        # Process operations sequentially on the matrix
        result = [row[:] for row in matrix]

        for op in operations:
            if op == 'R':
                for i in range(n):
                    i_list = result[i]
                    if i_list:
                        i_list.append(i_list[0])
                        i_list.pop(0)
                result = [row[:] for row in result]
            elif op == 'L':
                for i in range(n):
                    i_list = result[i]
                    if i_list:
                        result[i] = i_list[1:] + [i_list[0]]
            elif op == 'D':
                n_rows = len(result)
                if n_rows > 0:
                    first_row = result[0][:]
                    for i in range(n_rows):
                        result[i] = result[(i + 1) % n_rows][:]
                result = [row[:] for row in result]
            elif op == 'U':
                n_rows = len(result)
                if n_rows > 0:
                    last_row = result[n_rows - 1][:]
                    for i in range(n_rows):
                        result[(i + 1) % n_rows] = result[(i) % n_rows][:]
                result = [row[:] for row in result]
            elif op == 'I':
                new_result = []
                for i in range(n):
                    inv_row = compute_inverse(result[i])
                    new_result.append(inv_row)
                result = new_result
            elif op == 'C':
                n_rows = len(result)
                new_result = [[0] * n for _ in range(n)]
                for j in range(n):
                    original_col = [result[i][j] for i in range(n_rows)]
                    inv_col = compute_inverse(original_col)
                    for i in range(n_rows):
                        new_result[i][j] = inv_col[i]
                result = new_result

        output.append('\n'.join(' '.join(map(str, row)) for row in result))

    return '\n\n'.join(output)


