def rev(n):
    """Return the reverse of a number."""
    return int(str(n)[::-1])

def solution(input_str):
    if not input_str:
        return "-1"

    parts = input_str.strip().split()
    if len(parts) < 3:
        return "-1"

    try:
        maxx, maxy, w = int(parts[0]), int(parts[1]), int(parts[2])
    except:
        return "-1"

    # Generate all lucky pairs (a, b) where a*b = rev(a)*rev(b)
    lucky_pairs = []
    for a in range(1, maxx + 1):
        ra = rev(a)
        for b in range(1, maxy + 1):
            if a * b == ra * rev(b):
                lucky_pairs.append((a, b))

    if not lucky_pairs:
        return "-1"

    # Find minimum x * y with at least w lucky tickets
    best_ans = None
    min_total = float('inf')

    # For efficiency, precompute lucky groups by 'a'
    lucky_groups = {}
    for a, b in lucky_pairs:
        if a not in lucky_groups:
            lucky_groups[a] = []
        lucky_groups[a].append(b)
    for a in lucky_groups:
        lucky_groups[a].sort()

    # For each x, try to find minimum y
