def solution(input_str):
    n, m = map(int, input_str.split())

    MOD = 10**7 + 7

    # Precompute binomial coefficients
    def nCr(n, r):
        if r > n or r < 0:
            return 0
        elif r == 0 or r == n:
            return 1

        result = 1
        for i in range(r):
            result = result * (n - i) // (i + 1)
        return result

    # Count ways for left half from row 0 to t
    def count_left(t, k):
        # Need to count non-increasing sequences for c1 from [l, t]
        # available positions: at most (m-1)

        # Actually, let's use the formula directly
        # Number of non-decreasing sequences of length t+1 with values in range [1, m]
        # is C(t + (m-1), t)
        if m <= k:
            return 0
        return nCr(t + (m - 1 - k), t)

    # Count ways for right half from row t to r
    def count_right(r, k):
        return count_left(r, k)

    total = 0
    for t in range(n):  # pivot row (0-indexed)
        left_len = t + 1  # rows 0 to t: t+1 rows
        right_len = n - t  # rows t to n-1: n-t rows

        # Sum over all possible k (segment length)
        for k in range(1, m):
            left_ways = count_left(left_len - 1, k)
            right_ways = count_right(right_len - 1, k)

            ways = (left_ways * right_ways) % (10**7 + 7)
            total = (total + ways) % (10**7 + 7)

    return str(total)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    adj = []
    for i in range(1, n + 1):
        adj.append(lines[i])
    a = list(map(int, lines[n + 1].split()))

    def is_valid(attendees):
        """
        Check if the given set of attendees makes Igor lose
        For each employee:
        - If attending: messages received != predicted amount
        - If not attending: 0 messages != predicted amount (so predicted != 0)
        """
        messages = [0] * n
        for i in attendees:
            for j in range(n):
                if adj[i][j] == '1' and j in attendees:
                    messages[j] += 1

        for i in range(n):
            if i in attendees:
                if messages[i] == a[i]:
                    return False
            else:
                if a[i] == 0:
                    return False
        return True

    def backtrack(idx, current_attendees):
        """
        Recursive backtracking to find valid subset
        """
        if idx == n:
            # Base case: check if current subset is valid
            return current_attendees if is_valid(current_attendees) else None

        # Option 1: Include employee idx
        result = backtrack(idx + 1, current_attendees | {idx})
        if result:
            return result

        # Option 2: Exclude employee idx
        result = backtrack(idx + 1, current_attendees)
        return result

    result = backtrack(0, set())
    if result:
        result_list = sorted([x + 1 for x in result])  # Convert to 1-indexed
        return f"{len(result_list)}\n" + " ".join(map(str, result_list))
    else:
        return "-1"


