def solution(n_str):
    n = int(n_str)
    MOD = 10**9 + 7

    # Build trie of all valid bracket prefixes of length <= 2n
    # A valid prefix has i opening and j closing parens where i >= j
    states = set()
    states.add((0, 0))
    queue = [(0, 0)]

    while queue:
        i, j = queue.pop(0)

        # Try adding '('
        if i + 1 + j <= 2 * n:
            states.add((i + 1, j))
            queue.append((i + 1, j))

        # Try adding ')' if valid
        if i >= j + 1:
            states.add((i, j + 1))
            queue.append((i, j + 1))

    # Compute depth of each state using BFS
    depth = {}
    idx = 0
    while idx < len(queue):
        s = queue[idx]
        idx += 1
        if s in depth:
            continue
        depth[s] = 0
    queue = [(0, 0)]
    depth[(0, 0)] = 0

    while queue:
        i, j = queue.pop(0)
        if (i + 1, j) in states:
            if (i + 1, j) not in depth:
                depth[(i + 1, j)] = depth[(i, j)] + 1
            else:
                depth[(i + 1, j)] = depth[(i, j)] + 1
        if (i, j + 1) in states:
            if (i, j + 1) not in depth:
                depth[(i, j + 1)] = depth[(i, j)] + 1

    for s in states:
        depth[s] = depth.get(s, 0)

    # Sort states by depth descending (bottom-up for greedy matching)
    sorted_states = sorted(list(states), key=lambda s: -depth[s])

    # Greedy matching: match node with first available (unmatched) child
    matched = set()
    match_count = 0

    state_to_children = {}
    for i, j in states:
        children = []
        # Find children: parents for (i, j) would be (i-1, j) or (i, j-1)
        # So children are (i-1, j) and (i, j-1)
        if i > 0 and (i - 1, j) in states:
            children.append((i - 1, j))
        if j > 0 and (i, j - 1) in states:
            children.append((i, j - 1))
        state_to_children[(i, j)] = children

    # Process bottom-up
    for s in sorted_states:
        if s in matched:
            continue

        # Find an available unmatched child
        children = state_to_children[s]
        for c in children:
            if c not in matched:
                # Match s with c
                matched.add(s)
                matched.add(c)
                match_count += 1
                break

    return str(match_count % MOD)


