from math import isqrt

def solution(input_string):
    line = input_string.strip()
    n, m = map(int, line.split())

    roots = set()
    for b in range(1, n + 1):
        max_c = min(m, b * b)
        for c in range(1, max_c + 1):
            d = b * b - c
            if d == 0:
                roots.add(-b)
            else:
                s = isqrt(d)
                if s * s == d:
                    roots.add(-b + s)
                    roots.add(-b - s)
                else:
                    # Represent irrational uniquely
                    # Since -b + sqrt(d) and -b - sqrt(d) are distinct
                    # and different (b,c) with different d give different irrationals
                    roots.add((-b, d))  # Use tuple as unique key for irrational
                    roots.add((-b, -d))  # The other one

    return str(len(roots)) + "\n"
